import pathlib,json,html,sys,random
R=pathlib.Path(__file__).parent
first='--first' in sys.argv
sources=json.loads((R/'sources.json').read_text(encoding='utf8'))
notes=[
('Kinderdijk','The windmill country','Where the sky has room to breathe','The mills stand so quietly you almost forget they were built to work. I would happily lose an afternoon following their reflections.','A little wind, a lot of sky.','Windmills beside a reed-lined canal under blue winter sky.'),
('Amsterdam','The canal belt','A city written in curves','From up here the canals look like a thought someone kept circling back to. Down there, surely, a tiny table is waiting beside the water.','Follow the water. Get wonderfully lost.','An aerial view of concentric canals, brick roofs and narrow streets.'),
('Giethoorn','The village on the water','Taking the slow way, on purpose','A bridge, a bend, another patch of green. This feels like the sort of place where arriving late might be the whole point.','No hurry beyond this bridge.','A narrow canal, waterside houses, trees and an arched footbridge.'),
('Hoorn','At the old harbour','Keeping an eye on the water','The old tower has the best seat in the harbour. I like the little boats around it, looking as though they have just stopped by for a chat.','Meet me by the tower.','The Hoofdtoren beside Hoorn harbour, with boats and waterfront buildings.'),
('Keukenhof','A garden in full colour','Too many favourites to pick just one','I meant to choose a favourite colour. Then another flower bed appeared, and I had to start all over again.','A page is hardly enough for spring.','Spring flowers and trees in the Keukenhof gardens.'),
('Afsluitdijk','Between two waters','A very long line through the blue','Here the horizon does most of the talking. The road keeps going, and for once I am perfectly happy not to add anything.','Blue on both sides.','A long causeway carrying a road between two expanses of water.'),
('Delft','Above the rooftops','Terracotta, church bells, a patch of sky','All those little roofs, tucked close together. I keep finding another window, another chimney, another reason not to turn the page yet.','A city collected one roof at a time.','Delft rooftops seen from the Nieuwe Kerk toward the Oude Kerk.'),
('Zaanse Schans','Beside the Zaan','One last turn of the sails','The green timber and the water belong together so nicely. A good place to close the notebook, with a little room left for coming back.','Until the next little adventure.','Traditional buildings and windmills at Zaanse Schans.')]

def poly(points,fill):return f'<polygon points="{points}" fill="{fill}"/>'
def path(d,fill='none',stroke=None,width=2):return f'<path d="{d}" fill="{fill}"'+(f' stroke="{stroke}" stroke-width="{width}" stroke-linecap="round" stroke-linejoin="round"' if stroke else '')+'/>'
def rect(x,y,w,h,c):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" fill="{c}"/>'
def mill(x,y,s=1):
 return f'<g transform="translate({x} {y}) scale({s})">'+poly('-19,0 19,0 12,-67 -8,-69','#605544')+poly('-12,-68 13,-68 8,-79 -5,-82','#283e3d')+path('M2 -64 L-51 -72 M2 -64 L8 -121 M2 -64 L59 -57 M2 -64 L-5 -9','none','#344c4f',4)+path('M-51 -72 L-51 -81 L1 -72 M8 -121 L16 -121 L10 -65 M59 -57 L59 -48 L3 -56 M-5 -9 L-14 -10 L-6 -62','none','#c4bb9b',3)+rect(-3,-29,7,28,'#b5a77d')+'</g>'
def scene(n):
 b='';random.seed(22+n)
 if n==0:
  b=rect(0,0,600,410,'#96c4d6')+path('M0 70 Q130 90 240 60 T600 70 L600 0 L0 0Z','#72aed0')+path('M0 224 L600 215 L600 410 L0 410Z','#76a6bb')+path('M0 223 L0 205 171 207 293 215 344 219 289 229 103 252 0 249Z','#929266')+path('M600 214 L475 212 419 224 461 237 600 252Z','#7d8058')
  for x,y,s in [(186,214,1.35),(261,215,.6),(302,218,.35),(326,219,.22)]:
   b+=f'<g opacity=".28" transform="translate(0 {y*2}) scale(1 -1)">'+mill(x,y,s)+'</g>'+mill(x,y,s)
  b+=path('M600 410 L600 257 523 245 487 283 452 310 437 410Z','#7d7954')+path('M0 313 L87 326 107 353 0 370Z','#777b4c')
  for i in range(90):
   x=random.randint(0,600);y=random.randint(340,425)
   if x<125 or x>420 or y>395:b+=path(f'M{x} {y} l{random.randint(-22,15)} -{random.randint(18,70)}','none',random.choice(['#ac9b62','#756d42','#c2ad73']),2)
  b+=path('M460 286 L477 237 551 244 540 293 M472 254 L546 263 M462 278 L541 282','none','#605f43',4)
 else:b=SCENES[n]()
 # Tiny deterministic pigment flecks are vector grain, never a photo texture or trace.
 for i in range(1150):
  x=random.randint(2,598);y=random.randint(2,408)
  b+=f'<circle cx="{x}" cy="{y}" r="{random.choice([.4,.7,1])}" fill="{random.choice(["#f8f2de","#273f47"])}" opacity=".13"/>'
 return f'<svg viewBox="0 0 600 410" role="img" aria-label="Original acrylic-marker interpretation of {notes[n][0]}" xmlns="http://www.w3.org/2000/svg"><title>{notes[n][0]} — original vector illustration</title>{b}</svg>'
SCENES={}
# Scene definitions inserted after the first-spread review.
extra=R/'scene_parts.py'
if extra.exists():exec(extra.read_text(encoding='utf8'))
css='''@import url('https://fonts.googleapis.com/css2?family=Caveat:wght@400;600;700&display=swap');
:root{--ink:#243e50;--paper:#f6f1e4;--blue:#234d6b;--desk:#c2d0d0;--accent:#a84836;--hand:'Caveat',cursive}*{box-sizing:border-box}body{margin:0;background:var(--desk);color:var(--ink);font:16px/1.5 Georgia,serif}button,a,select{-webkit-tap-highlight-color:transparent}button,select{font:inherit}button{cursor:pointer}a{color:inherit;text-underline-offset:4px}button:focus-visible,a:focus-visible,select:focus-visible{outline:3px solid #a84836;outline-offset:5px}::selection{background:#e5b68f;color:#16364c}body{scrollbar-color:#567783 #c2d0d0}header{max-width:1220px;margin:auto;padding:23px 26px;display:flex;align-items:center;justify-content:space-between;font:14px/1.4 Georgia,serif}header a{text-decoration:none}header .brand{font-family:var(--hand);font-size:27px;font-weight:700}header nav{display:flex;gap:24px}.stage{padding:18px 34px 26px;min-height:665px;display:grid;place-items:center;perspective:1600px}.book{width:min(1120px,100%);position:relative;touch-action:pan-y}.spread{display:grid;grid-template-columns:1fr 1fr;min-height:585px;background:var(--paper);box-shadow:4px 14px 28px #324b4a36,0 3px 4px #324b4a30;border-radius:3px 9px 9px 3px;position:relative;isolation:isolate}.spread:after{content:'';position:absolute;inset:0 auto 0 50%;width:30px;transform:translateX(-50%);background:linear-gradient(90deg,transparent,#5f513418,transparent);pointer-events:none}.page{position:relative;padding:36px 39px 30px;min-width:0}.place{display:flex;align-items:center;justify-content:space-between;gap:12px}.place h2{font:600 41px/1 var(--hand);margin:0}.stamp{width:63px;height:63px;flex-shrink:0;border:2px solid #7c6f54;border-radius:50%;display:grid;place-content:center;text-align:center;transform:rotate(12deg);font:10px/1.5 Georgia,serif;color:#706345}.subtitle{font-size:12px;margin:6px 0 28px;color:#53626a}.polaroid{position:relative;background:#fffdf6;padding:12px 12px 20px;box-shadow:1px 5px 12px #33424625;transform:rotate(-2deg);margin:0 6px 22px}.polaroid:before,.polaroid:after{content:'';position:absolute;width:89px;height:27px;background:#d7b777a3;top:-11px;left:8px;transform:rotate(-24deg);z-index:1}.polaroid:after{left:auto;right:4px;transform:rotate(25deg);background:#a6bcb4b8}.polaroid img{display:block;width:100%;aspect-ratio:1.48;object-fit:contain;background:#eee9dc}.polaroid figcaption{text-align:center;font:23px/1.2 var(--hand);padding-top:10px}.caption{font:24px/1.25 var(--hand);margin:15px 9px;max-width:37ch}.drawing-page{display:flex;flex-direction:column;justify-content:center}.drawing{margin:0;transform:rotate(.4deg)}.drawing svg{width:100%;display:block;overflow:hidden}.drawing figcaption{font:25px/1.2 var(--hand);text-align:center;margin:24px 0 30px}.folio{position:absolute;bottom:15px;left:38px;right:38px;display:flex;justify-content:space-between;font-size:10px;color:#586569}.corner{position:absolute;bottom:0;right:0;width:54px;height:54px;border:0;border-radius:0 0 8px 0;background:linear-gradient(135deg,transparent 50%,#ded7c5 51%,#eee7d7 75%);color:var(--ink);font-size:18px;padding:22px 4px 0 23px}.corner:hover{background:linear-gradient(135deg,transparent 40%,#d1c7af 41%,#eee7d7 75%)}.cover{background:linear-gradient(90deg,#20445f 0 15px,var(--blue) 15px);color:#f3e8c9;width:min(510px,100%);min-height:590px;margin:auto;box-shadow:7px 15px 25px #263e4d44,inset 11px 0 10px #173c58;transform:rotate(-2deg);border-radius:4px 12px 12px 4px;padding:58px 42px 32px;text-align:center;position:relative;border:0}.cover:after{content:'';position:absolute;right:23px;top:-7px;bottom:-7px;width:10px;background:#9f4839;box-shadow:2px 0 4px #16394d40}.cover h1{font:600 clamp(47px,5vw,67px)/.95 var(--hand);margin:0 0 26px}.cover h1 span{display:block;font-size:.57em;line-height:1.5}.cover svg{width:150px;height:153px;margin:4px auto 18px;display:block}.cover p{font:23px/1.3 var(--hand);margin:8px}.open{color:#f4e9cf;background:transparent;border:1px solid #d5cca788;padding:11px 23px;margin-top:27px;border-radius:3px;font:23px var(--hand)}.open:hover{background:#315c7a}.controls{max-width:860px;margin:9px auto 0;padding:0 24px;display:flex;justify-content:center;align-items:center;gap:20px}.controls button{width:49px;height:45px;border:1px solid #70878a;background:transparent;border-radius:50%;color:var(--ink);display:grid;place-items:center}.controls button:hover:not(:disabled){background:#dce4df}.controls button:disabled{opacity:.3;cursor:default}.controls svg{width:20px;height:20px}.controls select{max-width:230px;background:transparent;color:var(--ink);border:0;border-bottom:1px solid #819597;padding:8px 20px 8px 4px;font-size:14px}.hint{text-align:center;margin:15px 20px 27px;font-size:12px;color:#405963}.title-page{text-align:center;display:flex;flex-direction:column;justify-content:center}.title-page h2{font:600 53px/.98 var(--hand);margin:20px 0}.title-page p{max-width:32ch;margin:15px auto}.title-page .hand{font:28px/1.2 var(--hand)}.contents h2{font:600 36px var(--hand);margin:0 0 15px}.contents button{display:flex;justify-content:space-between;width:100%;background:none;border:0;border-bottom:1px solid #d7d0bc;padding:9px 0;color:var(--ink);text-align:left;font:24px var(--hand)}.contents button:hover{color:var(--accent)}.closing h2{font:600 58px/1 var(--hand);margin:12px 0 30px}.closing p{max-width:32ch}.closing .hand{font:28px/1.2 var(--hand)}.credits{max-width:960px;margin:50px auto;padding:32px 28px;background:#d8e1db;border-radius:4px}.credits h2{font:600 39px/1.1 var(--hand);margin:0 0 18px}.credits p{max-width:74ch;font-size:14px}.credits ol{columns:2;column-gap:35px;padding-left:22px;font-size:13px}.credits li{break-inside:avoid;padding:0 0 17px 5px}.credits h3{margin:0;font-size:15px}.credits small{display:block;font-size:12px;margin-top:4px}.turning{animation:turn .38s cubic-bezier(.16,1,.3,1)}@keyframes turn{from{transform:rotateY(-7deg);filter:brightness(.92)}to{transform:rotateY(0);filter:brightness(1)}}footer{font-size:12px;text-align:center;padding:0 20px 32px}.book.dragging{transform:rotateY(var(--drag,0deg));transform-origin:left center}.grain{pointer-events:none;position:absolute;inset:0;opacity:.05} @media(max-width:700px){header{padding:15px 18px}header .brand{font-size:23px}header nav{gap:15px;font-size:12px}.stage{padding:12px 15px 14px;min-height:0}.cover{min-height:536px;padding:42px 22px 30px}.cover h1{font-size:56px}.spread{grid-template-columns:1fr}.spread:after{display:none}.page{padding:28px 25px 35px}.place h2{font-size:38px}.stamp{width:54px;height:54px}.subtitle{margin-bottom:25px}.polaroid{margin-left:2px;margin-right:2px}.caption{font-size:24px}.drawing-page{border-top:1px solid #ddd6c3;padding-top:30px;padding-bottom:30px}.drawing figcaption{margin-bottom:22px}.folio{left:25px;right:25px}.controls{gap:13px;margin-top:12px}.controls select{width:205px}.credits{margin:40px 15px;padding:26px 23px}.credits ol{columns:1}.title-page{min-height:430px}.title-page h2{font-size:49px}.contents{padding-bottom:44px}.closing{min-height:450px}.hint{max-width:300px;margin:17px auto 25px}.cover:after{right:13px}.drawing svg{aspect-ratio:600/410}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important;scroll-behavior:auto!important}.book.dragging{transform:none}}'''
arrow='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M4 12h16M14 6l6 6-6 6"/></svg>'
cover=f'''<section class="cover" aria-label="Sketchbook cover"><h1><span>A Sketchbook of</span>the Netherlands</h1><svg viewBox="0 0 160 160" aria-hidden="true" fill="none" stroke="#e7dbb8" stroke-width="2"><path d="M55 140l15-75h26l14 75M67 65l15-13 16 13M82 61V9m0 52h55M82 61v61M82 61H25M88 9h-6v45M137 67v-6H89M76 122h6V68M25 55v6h50M42 145h85M17 151h124"/></svg><p>Eight places. A pocketful of colour.</p><p>An imagined journey, in ink & paper.</p><button class="open" data-page="1">Open the sketchbook</button></section>'''
title='<section class="spread"><div class="page title-page"><h2>A Sketchbook<br>of the Netherlands</h2><p class="hand">For the places that make<br>you slow down.</p><p>An imagined spring itinerary<br>18–25 April · no particular year</p><p style="font-size:12px">Found photographs. Original words.<br>Eight places, seen twice.</p><span class="folio">The journey begins here</span></div><div class="page contents"><h2>Places to linger</h2>'+''.join(f'<button data-page="{i+2}"><span>{n[0]}</span><span>{i+1:02}</span></button>' for i,n in enumerate(notes if not first else notes[:1]))+'<p class="hand">Take a little detour.</p></div></section>'
pages=[cover,title]
for i,n in enumerate(notes[:1] if first else notes):
 pages.append(f'''<section class="spread" aria-label="{n[0]} spread"><div class="page"><div class="place"><h2 lang="nl">{n[0]}</h2><div class="stamp">NEDERLAND<br>{i+1:02} / VIII<br>REISBOEK</div></div><p class="subtitle">{n[2]}</p><figure class="polaroid"><img src="photos/{i+1:02}.jpg" alt="{n[5]}" width="600" height="405"><figcaption>{n[1]}</figcaption></figure><p class="caption">{n[3]}</p><div class="folio"><span>FOUND PHOTOGRAPH · ORIGINAL WORDS</span><span>{i*2+1:02}</span></div></div><div class="page drawing-page"><figure class="drawing">{scene(i)}<figcaption>{n[4]}</figcaption></figure><div class="folio"><span>AN ORIGINAL VECTOR STUDY</span><span>{i*2+2:02}</span></div><button class="corner" aria-label="Turn to the next page" data-next><span aria-hidden="true">›</span></button></div></section>''')
if not first:pages.append('<section class="spread"><div class="page closing"><h2>A little more<br>room for wonder.</h2><p class="hand">The notebook closes.<br>The looking does not.</p><p>Eight borrowed views, eight fresh interpretations. Thank you to the photographers who made these small escapes possible.</p><button class="open" style="color:var(--ink);border-color:#819597" data-page="0">Back to the cover</button></div><div class="page title-page"><h2>Tot de<br>volgende keer.</h2><p class="hand">Until next time.</p><p>Every photograph has a story beyond this book. <a href="#credits">Meet the photographers below.</a></p><span class="folio">Einde · The end</span></div></section>')
credits=''.join(f'<li><h3>{notes[i][0]}</h3><span>{html.escape(s["author"])}</span> · <a href="{s["licenseUrl"]}">{s["license"]}</a><br><a href="{s["source"]}">Original on Wikimedia Commons</a><small>Resized and metadata removed. Illustration is an original interpretation, shared under {s["license"]}.</small></li>' for i,s in enumerate(sources))
script='''const pages=PAGE_DATA;let current=0;const book=document.getElementById('book'),jump=document.getElementById('jump'),prev=document.getElementById('prev'),next=document.getElementById('next');function show(n,animate=true){current=Math.max(0,Math.min(pages.length-1,n));book.innerHTML=pages[current];book.classList.remove('turning');if(animate&&!matchMedia('(prefers-reduced-motion: reduce)').matches){void book.offsetWidth;book.classList.add('turning')}jump.value=current;prev.disabled=current===0;next.disabled=current===pages.length-1;document.getElementById('status').textContent=jump.options[current].text;history.replaceState(null,'','#page-'+current)}prev.onclick=()=>show(current-1);next.onclick=()=>show(current+1);jump.onchange=()=>show(+jump.value);book.onclick=e=>{let b=e.target.closest('[data-page],[data-next]');if(b)show(b.hasAttribute('data-next')?current+1:+b.dataset.page)};document.addEventListener('keydown',e=>{if(['SELECT','INPUT','TEXTAREA'].includes(document.activeElement.tagName))return;if(e.key==='ArrowRight'){e.preventDefault();show(current+1)}if(e.key==='ArrowLeft'){e.preventDefault();show(current-1)}if(e.key==='Home')show(0);if(e.key==='End')show(pages.length-1)});let drag=null,suppress=false;book.addEventListener('pointerdown',e=>{if(e.target.closest('button:not(.corner),a,select'))return;const r=book.getBoundingClientRect();const corner=e.clientX>r.right-85&&e.clientY>r.bottom-85;if(e.pointerType==='touch'||corner){drag={x:e.clientX,y:e.clientY,corner};if(book.hasPointerCapture(e.pointerId)||e.isTrusted)book.setPointerCapture(e.pointerId)}});book.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x;if(drag.corner){book.classList.add('dragging');book.style.setProperty('--drag',Math.max(-12,Math.min(12,dx/20))+'deg')}});book.addEventListener('pointerup',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;book.classList.remove('dragging');if(Math.abs(dx)>55&&Math.abs(dx)>Math.abs(dy)){suppress=true;show(current+(dx<0?1:-1));setTimeout(()=>suppress=false,0)}drag=null});book.addEventListener('click',e=>{if(suppress){e.preventDefault();e.stopImmediatePropagation()}},true);book.addEventListener('pointercancel',()=>{drag=null;book.classList.remove('dragging')});show(parseInt(location.hash.replace('#page-',''))||0,false);'''.replace('PAGE_DATA',json.dumps(pages,ensure_ascii=False))
options=['The cover','Before we go']+[n[0] for n in (notes[:1] if first else notes)]+([] if first else ['Until next time'])
output=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#234d6b"><meta name="description" content="Eight Dutch places, seen twice. An interactive travel sketchbook pairing licensed photographs with original acrylic-marker SVG illustrations."><title>A Sketchbook of the Netherlands</title><style>{css}</style></head><body><header><a class="brand" href="#" onclick="show(0);return false">A Dutch little detour</a><nav aria-label="About this book"><a href="#credits">Photo credits</a><a href="#making">The making</a></nav></header><main><div class="stage"><div id="book" class="book">{cover}</div></div><div class="controls" aria-label="Page navigation"><button id="prev" aria-label="Previous page" style="transform:rotate(180deg)">{arrow}</button><label for="jump" hidden>Choose a page</label><select id="jump">{''.join(f'<option value="{i}">{n}</option>' for i,n in enumerate(options))}</select><button id="next" aria-label="Next page">{arrow}</button></div><p class="hint">Turn a corner, use your arrow keys, or swipe.<br>A slow journey is a good journey.</p><div id="status" role="status" aria-live="polite" style="position:absolute;width:1px;height:1px;overflow:hidden"></div><section id="credits" class="credits"><h2>A thank-you to the photographers</h2><p>This is an imagined itinerary, not a record of a personal trip. All photographs come from Wikimedia Commons, not a private camera roll. Captions and vector illustrations were newly authored for this book. The photographs retain their original licences; no endorsement is implied.</p><ol>{credits}</ol><p>Illustrations are synthetic, shape-by-shape SVG interpretations, not embedded or traced photos. Each is offered under the corresponding photograph’s licence above. Source records: <a href="sources.json">sources.json</a> · Traveller’s notes: <a href="notes.md">notes.md</a>.</p></section><section id="making" class="credits"><h2>How this was made</h2><p>Following <a href="https://nelsonxlee.substack.com/p/turn-your-trip-photos-into-a-digital">“Turn Trip Photos Into a Digital Sketchbook” by Nelson Lee</a>. The method: prepare photos, write notes, build and check the cover and first spread, complete the book, then refine individual illustrations.</p><p>Substitution: this implementation uses code-authored SVG and vanilla JavaScript rather than the guide’s Claude Code / Opus workflow. No paid image service, image generation API or external JavaScript library was used. Caveat is the single handwritten Google Font.</p><p>Photos were saved as numbered JPEGs at 1600px on the long edge with metadata removed, including GPS. Originals were preserved privately in the build folder. Their capture dates span different years; this book deliberately follows an imagined route rather than claiming one chronological trip. Original colours inspired each drawing’s limited marker palette. Small vector pigment flecks provide paper grain.</p></section></main><footer>Made for the pleasure of looking. <a href="https://github.com/raj-microsoft/sketchbook-nl">View the source</a></footer><script>{script}</script></body></html>'''
(R/'index.html').write_text(output,encoding='utf8')
(R/'notes.md').write_text('# A Sketchbook of the Netherlands\n\nOriginal captions for an imagined itinerary; not personal travel testimony. Sources are ordered by the authored route, not capture date.\n\n'+'\n\n'.join(f'## {i+1:02}.jpg\nWhat is visible: {n[5]}\nPlace: {n[0]} — {n[1]}\nMemory / authored caption: {n[3]}\nDrawing caption: {n[4]}' for i,n in enumerate(notes)),encoding='utf8')
print('Built',len(pages),'pages; first-spread checkpoint:',first)
